-- Newsletter DRAFTS generated by scripts/newsletter-drafts/build.mts.
-- Inserts as status 'draft' / stage 'early'; nothing here schedules or sends.
-- Skips any draft whose title already exists. Safe to re-run.

-- signal-photos-live
insert into public.newsletters
  (title, subject, preheader, audience, blocks, status, stage)
select
  'Signal photos are live',
  '📸 The Signal photos are here',
  '320 photos from the afternoon, ready to browse and download.',
  'subscribers',
  $nl$[{"id":"signal-photos-live-01","type":"header","text":"The Signal photos are here.","size":"lg"},{"id":"signal-photos-live-02","type":"image","src":"https://tedxnewy.com.au/images/newsletter/signal-photos-collage.jpg","alt":"Four photos from Signal: a speaker on the red circle, an applauding audience, two friends sharing a laugh and a guest in a blue suit","widthPct":"full","href":"https://tedxnewy.com.au/signal"},{"id":"signal-photos-live-03","type":"text","html":"<p>320 photos from Signal are now live on our website, captured on the day by our media partner Newy Digital.</p><p>Find yourself, your friends or your favourite moment from the afternoon, then browse and download the full set.</p>"},{"id":"signal-photos-live-04","type":"button","label":"See the Signal photos","href":"https://tedxnewy.com.au/signal","align":"center","theme":"red","variant":"solid"},{"id":"signal-photos-live-05","type":"text","html":"<p>The talks are next. We'll add each video to the same page as it goes live, so keep an eye on it.</p><p>Thank you for being part of Signal.</p><p>Will and the TEDxNewy team</p>"}]$nl$::jsonb,
  'draft',
  'early'
where not exists (
  select 1 from public.newsletters where title = 'Signal photos are live'
);
